def _build_parser(*,facade:Any)->Any:
 p=facade.argparse.ArgumentParser(description="Check alert policy threshold gates from metrics schema v1.");p.add_argument("--event-log-path",default="data/logs/events.jsonl");p.add_argument("--report-dir",default="reports/metrics");p.add_argument("--day",default=None);p.add_argument("--metrics-json-path",default="")
 for n,e,d,t in [("--llm-success-rate-min","ALERT_POLICY_LLM_SUCCESS_RATE_MIN",.70,float),("--llm-circuit-open-rate-max","ALERT_POLICY_LLM_CIRCUIT_OPEN_RATE_MAX",.30,float),("--execution-blocked-rate-max","ALERT_POLICY_EXECUTION_BLOCKED_RATE_MAX",.60,float),("--execution-approved-executed-gap-max","ALERT_POLICY_EXECUTION_APPROVED_EXECUTED_GAP_MAX",0,int),("--api-429-rate-max","ALERT_POLICY_API_429_RATE_MAX",.20,float),("--portfolio-guard-blocked-ratio-max","ALERT_POLICY_PORTFOLIO_GUARD_BLOCKED_RATIO_MAX",.70,float),("--portfolio-guard-strategy-budget-exceeded-max","ALERT_POLICY_PORTFOLIO_GUARD_STRATEGY_BUDGET_EXCEEDED_MAX",20,int)]: p.add_argument(n,type=t,default=(facade._env_int if t is int else facade._env_float)(e,d))
